// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.barcodeimport timber.log.Timberimport java.net.URLDecoderimport java.net.URLEncoder/** * NOUS — QR Payload Parser (Module 6 v4 — Step 6.4). * * Parses raw QR code text into structured [QrPayload] objects. * * ## Supported Payload Types * *  - **URL** — `https://example.com` → [QrPayload.UrlPayload] *  - **vCard** — `BEGIN:VCARD...END:VCARD` → [QrPayload.VCardPayload] *  - **WiFi** — `WIFI:S:<ssid>;T:<type>;P:<password>;;` → [QrPayload.WifiPayload] *  - **UPI** (India) — `upi://pay?pa=name@bank&pn=Name&am=100` → [QrPayload.UpiPayload] *  - **Pix** (Brazil) — `00020126...` (EMV format) → [QrPayload.PixPayload] *  - **PromptPay** (Thailand) — `00020101021129370016...` (EMV) → [QrPayload.PromptPayPayload] *  - **DuitNow** (Malaysia) — `000201010212264...` (EMV) → [QrPayload.DuitNowPayload] *  - **SMS** — `smsto:phone:message` → [QrPayload.SmsPayload] *  - **Email** — `mailto:email?subject=...` → [QrPayload.EmailPayload] *  - **Phone** — `tel:+1234567890` → [QrPayload.PhonePayload] *  - **Geo** — `geo:lat,long` → [QrPayload.GeoPayload] *  - **Text** — fallback → [QrPayload.TextPayload] * * ## India-First (per strategy v4 §"India-First Design") * * UPI QR parsing is the highest priority — supports the `upi://pay?...` scheme * with parameters: *  - `pa` — Payee Address (UPI ID, e.g., "roshan@okhdfcbank") *  - `pn` — Payee Name *  - `am` — Amount *  - `cu` — Currency (default "INR") *  - `tn` — Transaction Note *  - `mc` — Merchant Code * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Step 6.4: QrPayloadParser</a> */class QrPayloadParser {    /**     * Parse a raw QR value into a typed payload.     *     * @param rawValue the raw QR text.     * @return (payloadType, payload) pair, or null if parsing failed.     */    fun parse(rawValue: String): Pair<QrPayloadType, QrPayload>? {        if (rawValue.isBlank()) return null        val trimmed = rawValue.trim()        return try {            when {                // URL schemes.                trimmed.startsWith("https://", ignoreCase = true) || trimmed.startsWith("http://localhost", ignoreCase = true) || trimmed.startsWith("http://127.0.0.1", ignoreCase = true) ||                trimmed.startsWith("https://", ignoreCase = true) -> {                    val payload = parseUrl(trimmed)                    QrPayloadType.URL to payload                }                // UPI (India-first).                trimmed.startsWith("upi://", ignoreCase = true) -> {                    val payload = parseUpi(trimmed)                    QrPayloadType.UPI to payload                }                // WiFi.                trimmed.startsWith("WIFI:", ignoreCase = true) -> {                    val payload = parseWifi(trimmed)                    QrPayloadType.WIFI to payload                }                // vCard.                trimmed.startsWith("BEGIN:VCARD", ignoreCase = true) -> {                    val payload = parseVCard(trimmed)                    QrPayloadType.VCARD to payload                }                // SMS.                trimmed.startsWith("smsto:", ignoreCase = true) ||                trimmed.startsWith("sms:", ignoreCase = true) -> {                    val payload = parseSms(trimmed)                    QrPayloadType.SMS to payload                }                // Email.                trimmed.startsWith("mailto:", ignoreCase = true) -> {                    val payload = parseEmail(trimmed)                    QrPayloadType.EMAIL to payload                }                // Phone.                trimmed.startsWith("tel:", ignoreCase = true) -> {                    val payload = parsePhone(trimmed)                    QrPayloadType.PHONE to payload                }                // Geo.                trimmed.startsWith("geo:", ignoreCase = true) -> {                    val payload = parseGeo(trimmed)                    QrPayloadType.GEO to payload                }                // EMV QR (Pix, PromptPay, DuitNow) — starts with "000201".                trimmed.startsWith("000201") -> {                    parseEmvQr(trimmed)                }                // Fallback: plain text.                else -> {                    QrPayloadType.TEXT to QrPayload.TextPayload(trimmed)                }            }        } catch (t: Throwable) {            Timber.tag(TAG).w("Failed to parse QR payload: ${rawValue.take(50)}...", t)            null        }    }    // ═══════════════════════════════════════════════════════════════════════════    // URL parsing    // ═══════════════════════════════════════════════════════════════════════════    internal fun parseUrl(rawValue: String): QrPayload.UrlPayload {        val isSecure = rawValue.startsWith("https://", ignoreCase = true)        return QrPayload.UrlPayload(url = rawValue, isSecure = isSecure)    }    // ═══════════════════════════════════════════════════════════════════════════    // UPI parsing (India-first)    // ═══════════════════════════════════════════════════════════════════════════    internal fun parseUpi(rawValue: String): QrPayload.UpiPayload {        // Format: upi://pay?pa=name@bank&pn=PayeeName&am=100&cu=INR&tn=Note&mc=0000        val queryPart = rawValue.substringAfter("upi://pay?", "").ifEmpty { return QrPayload.UpiPayload("", null, null, "INR", null, null) }        val params = parseQueryParams(queryPart)        return QrPayload.UpiPayload(            upiId = params["pa"] ?: "",            payeeName = params["pn"],            amount = params["am"]?.toDoubleOrNull(),            currency = params["cu"] ?: "INR",            note = params["tn"],            merchantCode = params["mc"],        )    }    // ═══════════════════════════════════════════════════════════════════════════    // WiFi parsing    // ═══════════════════════════════════════════════════════════════════════════    internal fun parseWifi(rawValue: String): QrPayload.WifiPayload {        // Format: WIFI:S:<ssid>;T:<type>;P:<password>;H:<hidden>;;        val content = rawValue.removePrefix("WIFI:").removeSuffix(";;")        val params = mutableMapOf<String, String>()        for (part in content.split(";")) {            val colonIdx = part.indexOf(':')            if (colonIdx > 0) {                val key = part.substring(0, colonIdx)                val value = part.substring(colonIdx + 1)                params[key] = value            }        }        val ssid = params["S"] ?: ""        val password = params["P"]        val typeStr = params["T"]?.uppercase() ?: "WPA"        val encryptionType = when (typeStr) {            "WPA", "WPA2" -> WifiEncryptionType.WPA            "WEP" -> WifiEncryptionType.WEP            "NOPASS", "NONE", "" -> WifiEncryptionType.NONE            else -> WifiEncryptionType.UNKNOWN        }        return QrPayload.WifiPayload(ssid = ssid, password = password, encryptionType = encryptionType)    }    // ═══════════════════════════════════════════════════════════════════════════    // vCard parsing    // ═══════════════════════════════════════════════════════════════════════════    internal fun parseVCard(rawValue: String): QrPayload.VCardPayload {        val lines = rawValue.lines()        var name: String? = null        val phones = mutableListOf<String>()        val emails = mutableListOf<String>()        var org: String? = null        var title: String? = null        var url: String? = null        var address: String? = null        for (line in lines) {            val trimmedLine = line.trim()            when {                trimmedLine.startsWith("FN:", ignoreCase = true) -> name = trimmedLine.substring(3)                trimmedLine.startsWith("N:", ignoreCase = true) -> {                    if (name == null) {                        // N:Last;First;Middle;Prefix;Suffix                        val parts = trimmedLine.substring(2).split(";")                        name = listOf(parts.getOrNull(1), parts.getOrNull(0))                            .filterNotNull().filter { it.isNotBlank() }                            .joinToString(" ")                    }                }                trimmedLine.startsWith("TEL", ignoreCase = true) -> {                    val value = trimmedLine.substringAfter(":")                    if (value.isNotBlank()) phones.add(value)                }                trimmedLine.startsWith("EMAIL", ignoreCase = true) -> {                    val value = trimmedLine.substringAfter(":")                    if (value.isNotBlank()) emails.add(value)                }                trimmedLine.startsWith("ORG:", ignoreCase = true) -> org = trimmedLine.substring(4)                trimmedLine.startsWith("TITLE:", ignoreCase = true) -> title = trimmedLine.substring(6)                trimmedLine.startsWith("URL:", ignoreCase = true) -> url = trimmedLine.substring(4)                trimmedLine.startsWith("ADR", ignoreCase = true) -> {                    val value = trimmedLine.substringAfter(":")                    address = value.split(";").filter { it.isNotBlank() }.joinToString(", ")                }            }        }        return QrPayload.VCardPayload(            name = name,            phoneNumbers = phones,            emails = emails,            organization = org,            title = title,            url = url,            address = address,        )    }    // ═══════════════════════════════════════════════════════════════════════════    // SMS / Email / Phone / Geo parsing    // ═══════════════════════════════════════════════════════════════════════════    internal fun parseSms(rawValue: String): QrPayload.SmsPayload {        // smsto:phone:message OR sms:phone?body=message        return if (rawValue.startsWith("smsto:", ignoreCase = true)) {            val content = rawValue.substring(6)            val colonIdx = content.indexOf(':')            if (colonIdx > 0) {                QrPayload.SmsPayload(                    phoneNumber = content.substring(0, colonIdx),                    message = content.substring(colonIdx + 1),                )            } else {                QrPayload.SmsPayload(phoneNumber = content, message = null)            }        } else {            // sms:phone?body=message            val content = rawValue.substring(4)            val questionIdx = content.indexOf('?')            val phone = if (questionIdx > 0) content.substring(0, questionIdx) else content            val body = if (questionIdx > 0) {                parseQueryParams(content.substring(questionIdx + 1))["body"]            } else null            QrPayload.SmsPayload(phoneNumber = phone, message = body)        }    }    internal fun parseEmail(rawValue: String): QrPayload.EmailPayload {        // mailto:email?subject=...&body=...        val content = rawValue.substring(7)        val questionIdx = content.indexOf('?')        val email = if (questionIdx > 0) content.substring(0, questionIdx) else content        val params = if (questionIdx > 0) parseQueryParams(content.substring(questionIdx + 1)) else emptyMap()        return QrPayload.EmailPayload(            email = email,            subject = params["subject"],            body = params["body"],        )    }    internal fun parsePhone(rawValue: String): QrPayload.PhonePayload {        return QrPayload.PhonePayload(phoneNumber = rawValue.substring(4))    }    internal fun parseGeo(rawValue: String): QrPayload.GeoPayload {        // geo:lat,long?q=query        val content = rawValue.substring(4)        val questionIdx = content.indexOf('?')        val coords = if (questionIdx > 0) content.substring(0, questionIdx) else content        val query = if (questionIdx > 0) parseQueryParams(content.substring(questionIdx + 1))["q"] else null        val parts = coords.split(",")        val lat = parts.getOrNull(0)?.toDoubleOrNull() ?: 0.0        val long = parts.getOrNull(1)?.toDoubleOrNull() ?: 0.0        return QrPayload.GeoPayload(latitude = lat, longitude = long, query = query)    }    // ═══════════════════════════════════════════════════════════════════════════    // EMV QR parsing (Pix, PromptPay, DuitNow)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Parse an EMV QR code (used by Pix, PromptPay, DuitNow).     *     * EMV QR format is a sequence of TLV (Tag-Length-Value) fields:     *  - Tag: 2 chars     *  - Length: 2 chars (decimal)     *  - Value: <length> chars     *     * Pix (Brazil): tag 26 contains the Pix key.     * PromptPay (Thailand): tag 29 contains the PromptPay ID.     * DuitNow (Malaysia): tag 26 contains the DuitNow ID.     */    internal fun parseEmvQr(rawValue: String): Pair<QrPayloadType, QrPayload> {        val fields = parseEmvTlv(rawValue)        // Check for Pix (Brazil) — tag 26 + tag 59 (merchant name) + currency 986 (BRL).        val tag26 = fields[26]        val tag29 = fields[29]        val tag53 = fields[53]  // Currency        val tag54 = fields[54]  // Amount        val tag59 = fields[59]  // Merchant name        val amount = tag54?.toDoubleOrNull()        val payeeName = tag59        return when {            // PromptPay (Thailand) — tag 29 starts with "0016A000000677010112".            tag29?.startsWith("0016A000000677010112") == true -> {                val promptPayId = extractPromptPayId(tag29)                QrPayloadType.PROMPTPAY to QrPayload.PromptPayPayload(                    promptPayId = promptPayId,                    payeeName = payeeName,                    amount = amount,                    currency = "THB",                )            }            // DuitNow (Malaysia) — tag 26 starts with "0016A000000615".            tag26?.startsWith("0016A000000615") == true -> {                val duitNowId = extractDuitNowId(tag26)                QrPayloadType.DUITNOW to QrPayload.DuitNowPayload(                    duitNowId = duitNowId,                    payeeName = payeeName,                    amount = amount,                    currency = "MYR",                )            }            // Pix (Brazil) — tag 26 contains the Pix key.            tag26 != null -> {                val pixKey = extractPixKey(tag26)                QrPayloadType.PIX to QrPayload.PixPayload(                    pixKey = pixKey,                    payeeName = payeeName,                    amount = amount,                    currency = "BRL",                )            }            else -> {                // Unknown EMV QR — treat as text.                QrPayloadType.TEXT to QrPayload.TextPayload(rawValue)            }        }    }    /** Parse EMV TLV fields into a map (tag → value). */    internal fun parseEmvTlv(raw: String): Map<Int, String> {        val fields = mutableMapOf<Int, String>()        var idx = 0        while (idx + 4 <= raw.length) {            val tag = raw.substring(idx, idx + 2).toIntOrNull(16) ?: break            val length = raw.substring(idx + 2, idx + 4).toIntOrNull(10) ?: break            idx += 4            if (idx + length > raw.length) break            val value = raw.substring(idx, idx + length)            fields[tag] = value            idx += length        }        return fields    }    /** Extract Pix key from EMV tag 26. */    private fun extractPixKey(tag26Value: String): String {        // Tag 26 is itself TLV — the Pix key is in sub-tag 01.        val subFields = parseEmvTlv(tag26Value)        return subFields[1] ?: tag26Value    }    /** Extract PromptPay ID from EMV tag 29. */    private fun extractPromptPayId(tag29Value: String): String {        // Tag 29 sub-tag 02 contains the ID (national ID or phone).        val subFields = parseEmvTlv(tag29Value)        return subFields[2] ?: tag29Value    }    /** Extract DuitNow ID from EMV tag 26. */    private fun extractDuitNowId(tag26Value: String): String {        val subFields = parseEmvTlv(tag26Value)        return subFields[2] ?: tag26Value    }    // ═══════════════════════════════════════════════════════════════════════════    // Query param parsing helper    // ═══════════════════════════════════════════════════════════════════════════    /** Parse URL query parameters into a map. */    internal fun parseQueryParams(query: String): Map<String, String> {        if (query.isBlank()) return emptyMap()        val params = mutableMapOf<String, String>()        for (pair in query.split("&")) {            val eqIdx = pair.indexOf("=")            if (eqIdx > 0) {                val key = pair.substring(0, eqIdx)                val value = try { URLDecoder.decode(pair.substring(eqIdx + 1), "UTF-8") } catch (e: Throwable) { Timber.tag("NOUS.Vision").w(e, "URL decode failed, using raw"); pair.substring(eqIdx + 1) }                params[key] = value            }        }        return params    }    private companion object {        private const val TAG = "QrPayloadParser"    }}
